<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#17324d;font-size:12px}.header{border-bottom:2px solid #159a9c;margin-bottom:18px}.meta,.items,.totals{width:100%;border-collapse:collapse}.meta td,.items th,.items td,.totals td{padding:8px}.items th,.items td{border:1px solid #d7e2ea}.items th{background:#eef7f7}.totals{margin-top:15px;width:45%}.total{font-size:16px;font-weight:bold}</style></head><body><div class="header"><h1>فاتورة خدمات طبية</h1><p>{{ $invoice->number }}</p></div><table class="meta"><tr><td><strong>المريض:</strong> {{ trim(($patient->f_name ?? '').' '.($patient->l_name ?? '')) }}</td><td><strong>العيادة:</strong> {{ $clinic->name_ar ?? '—' }}</td></tr><tr><td><strong>الزيارة:</strong> #{{ $invoice->visit_id }}</td><td><strong>التاريخ:</strong> {{ optional($invoice->issued_at)->format('Y/m/d H:i') }}</td></tr></table><table class="items"><thead><tr><th>الخدمة</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->unit_price,2) }}</td><td>{{ number_format($item->total,2) }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>المجموع</td><td>{{ number_format($invoice->subtotal,2) }}</td></tr><tr><td>الحسم</td><td>{{ number_format($invoice->discount,2) }}</td></tr><tr><td>الضريبة</td><td>{{ number_format($invoice->tax,2) }}</td></tr><tr class="total"><td>الإجمالي</td><td>{{ number_format($invoice->total,2) }}</td></tr><tr><td>المدفوع</td><td>{{ number_format($invoice->paid,2) }}</td></tr><tr><td>المتبقي</td><td>{{ number_format($invoice->balance,2) }}</td></tr></table></body></html>
